export function helpAnswer(question){const q=question.toLowerCase();if(/kyc|verif|identity|document|selfie/.test(q))return {text:'Open Identity Verification, save your details, upload your ID and selfie, then submit for manual review. You can return to check your status.',label:'Identity verification',href:'#/kyc'};if(/password|reset|forgot/.test(q))return {text:'Use Forgot password on the sign-in page to request a reset link. New passwords need at least 8 characters. The eye icon shows or hides what you type.',label:'Reset password',href:'#/forgot-password'};if(/sign.?up|register|account|country|phone/.test(q))return {text:'Create an account with your name, email and password. Choose your country and calling code when adding a phone number, then confirm your email.',label:'Create account',href:'#/signup'};if(/deposit|withdraw|wallet|fund|balance/.test(q))return {text:'Deposits require a configured receiving address. Submit your transaction hash for manual verification before credit is added. Withdrawals are simulations: they hold your available site balance, send no funds, and can be cancelled to restore it.',label:'Deposit screen',href:'#/deposit'};if(/price|market|chart|data|trade/.test(q))return {text:'Market prices and charts come from Kraken. USD and USDT pairs are labelled separately. Buy/Sell remains an order preview; it does not execute trades.',label:'View markets',href:'#/markets'};return {text:'I can explain signup, passwords, identity verification, transfers and live market data. Choose a topic below or ask a question about one of those areas.'};}
export function mountHelpChat(){if(document.querySelector('#aurex-help'))return;const host=document.createElement('aside');host.id='aurex-help';host.setAttribute('aria-label','Aurexmarkets help');host.innerHTML='<button id="help-greeting" class="help-greeting">Hi, how can we help?</button><button id="help-launcher" class="help-launcher" aria-label="Open help chat" aria-controls="help-panel" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H3l2-5a8.5 8.5 0 1 1 16-3.5Z"/><path d="M8 10h8M8 14h5"/></svg></button><section id="help-panel" class="help-panel" role="dialog" aria-modal="false" aria-labelledby="help-title" hidden><header><div><strong id="help-title">Hi, how can we help?</strong><small>Quick help · automated answers</small></div><button id="help-close" aria-label="Close help chat">×</button></header><div id="help-messages" class="help-messages" role="log" aria-live="polite"><p class="help-reply">Welcome to Aurexmarkets. Choose a topic or type your question.</p></div><div class="help-topics">'+['Create account','Identity verification','Password help','Deposits & withdrawals','Live market data'].map(t=>'<button type="button" data-help-topic="'+t+'">'+t+'</button>').join('')+'</div><form id="help-form"><label class="sr-only" for="help-question">Your question</label><input id="help-question" autocomplete="off" placeholder="Type your question…" maxlength="500" required><button type="submit" aria-label="Send question">↑</button></form></section>';document.body.append(host);const panel=host.querySelector('#help-panel'),launcher=host.querySelector('#help-launcher'),greeting=host.querySelector('#help-greeting');const setOpen=open=>{panel.hidden=!open;greeting.hidden=open;launcher.setAttribute('aria-expanded',String(open));launcher.setAttribute('aria-label',open?'Close help chat':'Open help chat');if(open)host.querySelector('#help-question').focus();else launcher.focus();};launcher.onclick=()=>setOpen(panel.hidden);greeting.onclick=()=>setOpen(true);host.querySelector('#help-close').onclick=()=>setOpen(false);host.onkeydown=e=>{if(e.key==='Escape')setOpen(false);};function ask(question){const log=host.querySelector('#help-messages'),user=document.createElement('p');user.className='help-question';user.textContent=question;log.append(user);const answer=helpAnswer(question),reply=document.createElement('p');reply.className='help-reply';reply.textContent=answer.text;if(answer.href){const link=document.createElement('a');link.href=answer.href;link.textContent=answer.label;link.onclick=()=>setOpen(false);reply.append(document.createElement('br'),link);}log.append(reply);while(log.children.length>22)log.firstElementChild.remove();log.scrollTop=log.scrollHeight;}
host.querySelector('#help-form').onsubmit=e=>{e.preventDefault();const input=host.querySelector('#help-question'),q=input.value.trim();if(!q)return;ask(q);input.value='';};host.querySelectorAll('[data-help-topic]').forEach(b=>b.onclick=()=>ask(b.dataset.helpTopic));}
